Editor.prototype.act=function(a){if(a==='select'){this.post('selectQuantityAttributeObject',this.request());return;}if(a==='close'){this.post('close','');return;}if(!this.ctx||!this.ctx.selected)return;if(a==='save'){clearTimeout(this.calcTimer);this.requestSeq++;this.post('saveQuantityAttributes',this.request({requestId:-1}));}else if(a==='refresh')this.post('refreshQuantityAttributes',this.request());else if(a==='default')this.post('reloadQuantityAttributeDefault',this.request());else if(a==='start'||a==='end')this.post('selectQuantityAttributeNode',this.request({forStart:a==='start'}));else if(a==='legacy')this.post('openLegacyQuantityAttributeEditor',this.request());else if(a==='standalone')this.post('openQuantityAttributeEditorWindow',this.request());else if(a==='swap'){this.markDirty();this.scheduleDraft('SwapEndpoints',true);}};
function dispatch(c){instances.forEach(function(x){x.load(c);});}w.CDBoxQuantityAttributeEditorPage={create:function(o){var x=new Editor(o);instances.push(x);return x.init();}};w.CDBoxQuantityAttributeEditorLoad=dispatch;w.CDBoxQuantityAttributeEditorFailed=function(m){instances.forEach(function(x){x.toast(m,'error');});};})(window);
";
        }

        private static string Html(string value) { return (value ?? string.Empty).Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\"", "&quot;").Replace("'", "&#39;"); }
        private static string Js(string value) { return "'" + (value ?? string.Empty).Replace("\\", "\\\\").Replace("'", "\\'").Replace("\r", "\\r").Replace("\n", "\\n") + "'"; }
    }
